import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _load_document_bytes(document: Any) -> bytes:
    if isinstance(document, (bytes, bytearray)):
        return bytes(document)
    if isinstance(document, str):
        if document.startswith("s3://"):
            # Not supported for direct byte extraction in this implementation.
            raise ValueError("Expected raw document bytes or a local file path, not an s3:// URI.")
        with open(document, "rb") as f:
            return f.read()
    if hasattr(document, "read"):
        data = document.read()
        if isinstance(data, str):
            data = data.encode("utf-8")
        return bytes(data)
    raise TypeError("document must be bytes, bytearray, file path, or file-like object")


def _geometry_to_bbox(geometry: Optional[List[Dict[str, float]]]) -> Optional[Dict[str, float]]:
    if not geometry:
        return None
    xs = [p["X"] for p in geometry if "X" in p]
    ys = [p["Y"] for p in geometry if "Y" in p]
    if not xs or not ys:
        return None
    return {"left": min(xs), "top": min(ys), "width": max(xs) - min(xs), "height": max(ys) - min(ys)}


def extract_table_cells_and_rows(document: Any, region: str = "us-east-1") -> Dict[str, Any]:
    """
    Extract table cells and row structure from a document using Amazon Textract.

    Args:
        document: Raw bytes, local file path, or file-like object.
        region: AWS region for Textract.

    Returns:
        A dict containing detected tables, rows, and cells.
    """
    doc_bytes = _load_document_bytes(document)

    textract = boto3.client("textract", region_name=region)

    try:
        response = textract.analyze_document(
            Document={"Bytes": doc_bytes},
            FeatureTypes=["TABLES"],
        )
    except (BotoCoreError, ClientError) as e:
        raise RuntimeError(f"Textract analyze_document failed: {e}") from e

    blocks = response.get("Blocks", [])
    blocks_by_id = {b["Id"]: b for b in blocks if "Id" in b}

    tables = []
    for block in blocks:
        if block.get("BlockType") != "TABLE":
            continue

        table_info = {
            "table_id": block.get("Id"),
            "page": block.get("Page"),
            "bbox": _geometry_to_bbox(block.get("Geometry", {}).get("Polygon")),
            "rows": [],
            "cells": [],
        }

        cell_ids = [rel["Ids"] for rel in block.get("Relationships", []) if rel.get("Type") == "CHILD"]
        cell_ids = [cid for group in cell_ids for cid in group]

        cells_by_row: Dict[int, List[Dict[str, Any]]] = {}
        for cell_id in cell_ids:
            cell = blocks_by_id.get(cell_id)
            if not cell or cell.get("BlockType") != "CELL":
                continue

            text_parts = []
            for rel in cell.get("Relationships", []):
                if rel.get("Type") != "CHILD":
                    continue
                for child_id in rel.get("Ids", []):
                    child = blocks_by_id.get(child_id)
                    if child and child.get("BlockType") == "WORD":
                        text_parts.append(child.get("Text", ""))

            row_index = int(cell.get("RowIndex", 0))
            col_index = int(cell.get("ColumnIndex", 0))
            cell_entry = {
                "row_index": row_index,
                "column_index": col_index,
                "text": " ".join(tp for tp in text_parts if tp).strip(),
                "row_span": int(cell.get("RowSpan", 1)),
                "column_span": int(cell.get("ColumnSpan", 1)),
                "confidence": cell.get("Confidence"),
                "bbox": _geometry_to_bbox(cell.get("Geometry", {}).get("Polygon")),
                "cell_id": cell.get("Id"),
                "is_selected": cell.get("SelectionStatus") == "SELECTED",
            }
            table_info["cells"].append(cell_entry)
            cells_by_row.setdefault(row_index, []).append(cell_entry)

        for row_index in sorted(cells_by_row):
            row_cells = sorted(cells_by_row[row_index], key=lambda x: x["column_index"])
            table_info["rows"].append(
                {
                    "row_index": row_index,
                    "cells": row_cells,
                }
            )

        tables.append(table_info)

    return {
        "provider": "amazon-textract",
        "document_metadata": response.get("DocumentMetadata", {}),
        "tables": tables,
    }
